<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue';
import { ElMessage, ElMessageBox } from 'element-plus';
import { api } from '@/api';
import { staffAuth } from '@/auth';
const tab=ref('analytics');const loading=ref(false);const analytics=ref<any>({});const content=ref<any>({posts:[]});const notifications=ref<any>({candidate_outbox:[],staff_email_outbox:[]});const flags=ref<any[]>([]);const notices=ref<any[]>([]);const flagDialog=ref(false);const noticeDialog=ref(false);
const flagForm=reactive({key:'',name:'',description:'',enabled:false,rollout_percentage:0,operation_reason:''});const noticeForm=reactive({title:'',content:'',status:'draft',starts_at:null as any,ends_at:null as any,operation_reason:''});
const load=async()=>{loading.value=true;try{const jobs:Promise<any>[]=[];const keys:string[]=[];if(staffAuth.has('analytics.view')){jobs.push(api.get('/analytics/'));keys.push('analytics')}if(staffAuth.has('content.manage')){jobs.push(api.get('/content/operations/'));keys.push('content')}if(staffAuth.has('notifications.manage')){jobs.push(api.get('/notifications/operations/'));keys.push('notifications')}if(staffAuth.has('feature_flags.manage')){jobs.push(api.get('/feature-flags/'),api.get('/maintenance-notices/'));keys.push('flags','notices')}const values=await Promise.all(jobs);keys.forEach((key,index)=>{if(key==='analytics')analytics.value=values[index];if(key==='content')content.value=values[index];if(key==='notifications')notifications.value=values[index];if(key==='flags')flags.value=values[index];if(key==='notices')notices.value=values[index]})}finally{loading.value=false}};
const rebuild=async()=>{const{value}=await ElMessageBox.prompt('请输入重建公开内容索引原因','重建 Meilisearch',{inputType:'textarea'});await api.post('/content/operations/',{operation_reason:value});ElMessage.success('索引重建任务已进入队列。')};
const createFlag=async()=>{await api.post('/feature-flags/',flagForm);flagDialog.value=false;await load()};const toggleFlag=async(row:any)=>{const{value}=await ElMessageBox.prompt('请输入灰度状态调整原因','更新 Feature Flag',{inputType:'textarea'});await api.patch(`/feature-flags/${row.id}/`,{enabled:!row.enabled,operation_reason:value});await load()};
const createNotice=async()=>{await api.post('/maintenance-notices/',noticeForm);noticeDialog.value=false;await load()};onMounted(async()=>{if(!staffAuth.has('analytics.view'))tab.value=staffAuth.has('content.manage')?'content':staffAuth.has('notifications.manage')?'notifications':'flags';await load()});
</script>
<template><div class="page" v-loading="loading"><header class="page-header"><div><h1>治理与运营分析</h1><p>集中查看真实业务指标、公开内容索引、通知投递和灰度配置。</p></div><el-button @click="load">刷新</el-button></header><el-tabs v-model="tab" class="governance-tabs"><el-tab-pane v-if="staffAuth.has('analytics.view')" label="运营分析" name="analytics"><section class="metric-band"><div class="metric"><span>候选人总数</span><strong>{{analytics.candidate_total||0}}</strong><small>近 30 天新增 {{analytics.candidate_new||0}}</small></div><div class="metric"><span>模型请求</span><strong>{{analytics.model?.requests||0}}</strong><small>失败 {{analytics.model?.failures||0}}</small></div><div class="metric"><span>模型成本</span><strong>{{analytics.model?.cost||0}}</strong><small>近 30 天估算</small></div><div class="metric"><span>知识检索命中</span><strong>{{analytics.knowledge?.retrievals||0}}</strong><small>{{analytics.knowledge?.published||0}} 个发布文档</small></div></section><div class="analytics-grid"><div><h3>面试状态</h3><pre>{{JSON.stringify(analytics.interviews||{},null,2)}}</pre></div><div><h3>求职投递状态</h3><pre>{{JSON.stringify(analytics.applications||{},null,2)}}</pre></div><div><h3>异步任务状态</h3><pre>{{JSON.stringify(analytics.tasks||{},null,2)}}</pre></div></div></el-tab-pane><el-tab-pane v-if="staffAuth.has('content.manage')" label="内容与搜索" name="content"><div class="tab-actions"><el-button type="primary" @click="rebuild">重建公开索引</el-button></div><div class="metric-band compact"><div class="metric"><span>官方文章</span><strong>{{content.posts?.length||0}}</strong></div><div class="metric"><span>社区主题映射</span><strong>{{content.community_topics||0}}</strong></div><div class="metric"><span>失败 Webhook</span><strong>{{content.failed_webhooks||0}}</strong></div></div><div class="data-surface"><el-table :data="content.posts"><el-table-column prop="title" label="文章" /><el-table-column prop="author" label="作者" /><el-table-column prop="status" label="状态" /><el-table-column prop="is_featured" label="精选"><template #default="{row}">{{row.is_featured?'是':'否'}}</template></el-table-column><el-table-column prop="updated_at" label="更新时间" /></el-table></div></el-tab-pane><el-tab-pane v-if="staffAuth.has('notifications.manage')" label="通知投递" name="notifications"><h3>候选人通知 Outbox</h3><div class="data-surface"><el-table :data="notifications.candidate_outbox"><el-table-column prop="event_id" label="事件" /><el-table-column prop="status" label="状态" /><el-table-column prop="attempts" label="尝试" /><el-table-column prop="last_error" label="错误" /></el-table></div><h3>员工邀请邮件 Outbox</h3><div class="data-surface"><el-table :data="notifications.staff_email_outbox"><el-table-column prop="to_email" label="收件人" /><el-table-column prop="status" label="状态" /><el-table-column prop="attempts" label="尝试" /><el-table-column prop="last_error" label="错误" /><el-table-column prop="sent_at" label="发送时间" /></el-table></div></el-tab-pane><el-tab-pane v-if="staffAuth.has('feature_flags.manage')" label="灰度与公告" name="flags"><div class="tab-actions"><el-button @click="noticeDialog=true">维护公告</el-button><el-button type="primary" @click="flagDialog=true">新增 Feature Flag</el-button></div><div class="data-surface"><el-table :data="flags"><el-table-column prop="key" label="Key" /><el-table-column prop="name" label="名称" /><el-table-column label="灰度"><template #default="{row}">{{row.rollout_percentage}}%</template></el-table-column><el-table-column prop="version" label="版本" /><el-table-column label="状态"><template #default="{row}"><el-switch :model-value="row.enabled" @change="toggleFlag(row)" /></template></el-table-column></el-table></div><h3>维护公告</h3><div class="data-surface"><el-table :data="notices"><el-table-column prop="title" label="标题" /><el-table-column prop="status" label="状态" /><el-table-column prop="starts_at" label="开始" /><el-table-column prop="ends_at" label="结束" /></el-table></div></el-tab-pane></el-tabs>
<el-dialog v-model="flagDialog" title="新增 Feature Flag" width="520px"><el-form label-position="top"><el-form-item label="Key"><el-input v-model="flagForm.key" /></el-form-item><el-form-item label="名称"><el-input v-model="flagForm.name" /></el-form-item><el-form-item label="说明"><el-input v-model="flagForm.description" type="textarea" /></el-form-item><el-form-item label="灰度比例"><el-slider v-model="flagForm.rollout_percentage" /></el-form-item><el-form-item label="操作原因"><el-input v-model="flagForm.operation_reason" type="textarea" /></el-form-item></el-form><template #footer><el-button @click="flagDialog=false">取消</el-button><el-button type="primary" :disabled="!flagForm.key||!flagForm.name||!flagForm.operation_reason" @click="createFlag">创建</el-button></template></el-dialog><el-dialog v-model="noticeDialog" title="新增维护公告" width="560px"><el-form label-position="top"><el-form-item label="标题"><el-input v-model="noticeForm.title" /></el-form-item><el-form-item label="内容"><el-input v-model="noticeForm.content" type="textarea" /></el-form-item><el-form-item label="状态"><el-select v-model="noticeForm.status"><el-option label="草稿" value="draft" /><el-option label="已排期" value="scheduled" /><el-option label="展示中" value="active" /></el-select></el-form-item><el-form-item label="操作原因"><el-input v-model="noticeForm.operation_reason" type="textarea" /></el-form-item></el-form><template #footer><el-button @click="noticeDialog=false">取消</el-button><el-button type="primary" :disabled="!noticeForm.title||!noticeForm.operation_reason" @click="createNotice">创建</el-button></template></el-dialog></div></template>
<style scoped>.governance-tabs{margin-top:18px}.tab-actions{display:flex;justify-content:flex-end;gap:8px;margin-bottom:12px}.compact{grid-template-columns:repeat(3,1fr);margin-bottom:14px}.analytics-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-top:18px}.analytics-grid>div{padding:16px;border:1px solid #dfe3e8;background:#fff}.analytics-grid h3{margin-top:0}h3{margin:24px 0 12px}</style>
